async (page) => {
  const root='/Users/ffq/Documents/aicoding项目/gis校园地图/';
  const errors=[], captures=[], checks=[];
  page.on('pageerror',e=>errors.push(String(e)));
  page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
  await page.emulateMedia({reducedMotion:'reduce'});
  const assert=(value,message)=>{if(!value)throw Error(message)};
  const ready=async()=>{
    await page.waitForFunction(()=>document.querySelector('.atlas-map')?.tabIndex===0 && document.querySelector('.leaflet-image-layer')?.naturalWidth===7168 && !document.querySelector('.atlas-map')?.classList.contains('leaflet-zoom-anim'));
    await page.evaluate(()=>new Promise(resolve=>{let n=0;function next(){if(++n===12)resolve();else requestAnimationFrame(next)}requestAnimationFrame(next)}));
  };
  const goto=async(url)=>{await page.goto('http://127.0.0.1:5173/'+url);await ready()};
  const cat=async(name)=>{await page.getByRole('navigation',{name:'按用途查找'}).getByRole('button',{name:new RegExp('^'+name+' ')}).click();await ready()};
  const ids=()=>page.locator('.atlas-places button[data-record]').evaluateAll(nodes=>nodes.map(node=>node.dataset.record));
  const shot=async(name,criterion)=>{
    await ready();
    const state=await page.evaluate(async()=>{
      const img=document.querySelector('.leaflet-image-layer'),meta=await(await fetch('/campus-atlas.json',{cache:'no-store'})).json();
      const bytes=await(await fetch(img.src,{cache:'no-store'})).arrayBuffer();
      const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');
      return {url:location.href,image_url:img.src,image_sha256:hash,formal_image_sha256:meta.image_sha256,natural_size:[img.naturalWidth,img.naturalHeight],roof_hotspots:document.querySelectorAll('.atlas-building-hotspot').length,source_points:document.querySelectorAll('.atlas-source-point').length,overflow:document.documentElement.scrollWidth>innerWidth,map_height:document.querySelector('.atlas-map').clientHeight,selected:document.querySelector('.atlas-detail h2')?.textContent||null};
    });
    assert(!state.overflow && state.map_height>90,'Viewport overflow or unusable map '+name);
    assert(state.roof_hotspots===130 && state.source_points===7 && state.image_sha256===state.formal_image_sha256,'Map integrity '+name);
    const path='output/playwright/atlas-services-'+name+'.png';
    await page.screenshot({path:root+path});
    captures.push({path,criterion,viewport:page.viewportSize(),...state});
  };
  await page.setViewportSize({width:1280,height:720});
  await goto('');
  assert(new URL(page.url()).searchParams.get('area')==='all','Default must be overview');
  assert((await ids()).length===137,'Overview record count');
  await shot('overview','Default whole-campus entrance and six source-backed categories');
  const expected={ '教学建筑':29,'公寓建筑':63,'餐饮建筑':5,'配套建筑':33,'校门':3,'运动场':4 };
  for(const [name,count]of Object.entries(expected)){
    await cat(name);assert((await ids()).length===count,'Category count '+name);
    const active=await page.locator('[data-atlas-id]').evaluateAll(nodes=>nodes.filter(n=>getComputedStyle(n).pointerEvents!=='none').map(n=>n.dataset.atlasId));
    assert(active.length===count,'Map/list filter mismatch '+name);
    checks.push({category:name,count});
  }
  await cat('餐饮建筑');await shot('dining','Dining subset: same five records in list and roof hit layers, two regions');
  await page.locator('[data-record="N31"]').click();await ready();
  assert((await ids()).length===5,'Selecting category result must retain full filter');
  assert(new URL(page.url()).searchParams.get('building')==='N31','Building link');
  const detailUrl=page.url();await page.reload();await ready();
  assert(await page.locator('.atlas-detail h2').innerText()==='北区食堂主体','Filtered detail reload');
  await page.goBack();await ready();assert(await page.locator('.atlas-detail').count()===0,'Back restores filter');
  await page.goForward();await ready();assert(page.url()===detailUrl,'Forward restores selection');
  await page.getByRole('button',{name:/^关闭(建筑|地点)详情$/}).click();
  await cat('校门');
  for(const ident of ['place:gate1','place:gate2','place:gate3']){
    await page.locator(`[data-record="${ident}"]`).click();await ready();
    const position=await page.evaluate(async ident=>{
      const meta=await(await fetch('/campus-atlas.json')).json(),r=meta.map_places.records.find(r=>r.id===ident);
      const img=document.querySelector('.leaflet-image-layer').getBoundingClientRect(),point=document.querySelector(`[data-atlas-id="${ident}"]`).getBoundingClientRect(),card=document.querySelector('.atlas-detail').getBoundingClientRect();
      const expected=[img.left+r.anchor[0]*img.width/meta.width,img.top+r.anchor[1]*img.height/meta.height],actual=[point.x+point.width/2,point.y+point.height/2];
      return {id:ident,expected,actual,max_error_px:Math.max(...actual.map((v,i)=>Math.abs(v-expected[i]))),outside_card:actual[0]<card.left || actual[1]<card.top || actual[1]>card.bottom};
    },ident);
    assert(position.max_error_px<1.2 && position.outside_card,'Projected source point '+JSON.stringify(position));checks.push(position);
    if(ident==='place:gate3')await shot('gate','Source 3号门 anchor, independently projected screen position and separate place link');
    await page.getByRole('button',{name:/^关闭(建筑|地点)详情$/}).click();
  }
  await cat('运动场');
  await page.locator('[data-record="place:central-track"]').click();await ready();
  assert(new URL(page.url()).searchParams.get('place')==='place:central-track','Place link');
  await shot('track','Source stadium location/frame, retained original geometry and detail');
  await page.reload();await ready();assert(await page.locator('.atlas-detail h2').innerText()==='中区运动场','Place refresh');
  await cat('全部');
  const input=page.getByRole('textbox',{name:'搜索校园建筑'});
  for(const [q,expected]of [['S1','S01'],['Ｍ１','M01'],['N1','N01'],['六号','B06']]){
    await input.fill(q);assert((await ids())[0]===expected,'Normalized query '+q);checks.push({query:q,first:expected});
  }
  await input.fill('吃饭');assert((await ids()).length===5,'Dining alias');
  await input.fill('不存在的地点XYZ');assert(await page.locator('.atlas-empty').isVisible(),'Empty state');
  await page.getByRole('button',{name:'清除筛选，继续浏览'}).click();
  await input.fill('六号');await input.press('Enter');await ready();
  await page.locator('.atlas-photo-preview').click();assert(await page.locator('.atlas-photo-dialog').evaluate(d=>d.open),'Photo opens');
  await page.getByRole('button',{name:'关闭参考照片'}).click();
  await page.mouse.move(720,370);await page.mouse.down();await page.mouse.move(790,390,{steps:12});await page.mouse.up();await ready();
  const before=await page.locator('.leaflet-image-layer').boundingBox();
  await page.getByRole('button',{name:'复制建筑链接'}).click();
  await page.waitForFunction(()=>document.querySelector('.atlas-detail-share button')?.textContent!=='正在复制…');await ready();
  const after=await page.locator('.leaflet-image-layer').boundingBox();
  assert(Math.abs(before.x-after.x)<1 && Math.abs(before.y-after.y)<1,'Copy unexpectedly reframed map');checks.push({copy_kept_map:true});
  for(const viewport of [{width:390,height:844},{width:320,height:640},{width:844,height:390}]){
    await page.setViewportSize(viewport);await goto('?view=atlas&area=south');
    await input.fill('六号');await input.press('ArrowDown');await page.keyboard.press('Enter');await ready();
    if(viewport.width<=700)assert(await page.locator('.atlas-detail').evaluate(card=>card===document.activeElement),'Mobile detail focus');
    const framing=await page.evaluate(()=>{const roof=document.querySelector('[data-atlas-id="B06"]').getBoundingClientRect(),card=document.querySelector('.atlas-detail').getBoundingClientRect();return {roof_bottom:roof.bottom,card_top:card.top,roof_top:roof.top,roof_right:roof.right,card_left:card.left}});
    assert(framing.roof_bottom<framing.card_top+2 || (viewport.width>700 && framing.roof_right<framing.card_left+2),'Selected roof hidden by detail '+JSON.stringify(framing));
    await shot('mobile-'+viewport.width,'Keyboard search selection, visible roof, focus and constrained detail');
    await page.getByRole('button',{name:/^关闭(建筑|地点)详情$/}).click();
    await cat('运动场');await page.locator('[data-record="place:south-track"]').click();await ready();
    if(viewport.width===390)await shot('mobile-track','Mobile source stadium detail and readable field above card');
    await page.getByRole('button',{name:/^关闭(建筑|地点)详情$/}).click();await cat('校门');
    await page.locator('[data-record="place:gate3"]').click();await ready();
    if(viewport.width===320)await shot('mobile-gate','Narrow mobile source gate location without overflow');
  }
  await page.setViewportSize({width:1280,height:720});
  await goto('?view=atlas&area=lake&building=B06');
  await page.getByRole('link',{name:'卫星地图',exact:true}).click();
  await page.getByRole('link',{name:'鸟瞰地图',exact:true}).waitFor({state:'visible'});
  assert(new URL(page.url()).searchParams.get('view')==='satellite','Satellite route');
  await page.getByRole('link',{name:'鸟瞰地图',exact:true}).click();await ready();
  await page.goto('http://127.0.0.1:5173/?view=street');
  await page.getByRole('link',{name:'鸟瞰地图',exact:true}).waitFor({state:'visible'});
  assert(new URL(page.url()).searchParams.get('view')==='street','Street refresh');
  await page.reload();await page.getByRole('link',{name:'鸟瞰地图',exact:true}).waitFor({state:'visible'});
  assert(new URL(page.url()).searchParams.get('view')==='street','Street reload canonical');
  checks.push({symmetric_navigation:true,street_refresh:true});
  await goto('?view=atlas&area=south');
  await page.evaluate(()=>{history.pushState(null,'','?view=street');dispatchEvent(new PopStateEvent('popstate'))});
  await page.getByRole('link',{name:'鸟瞰地图',exact:true}).waitFor({state:'visible'});
  assert(new URL(page.url()).searchParams.get('view')==='street','Atlas handler rewrote street history');
  await page.evaluate(()=>{history.pushState(null,'','?view=atlas&area=lake');dispatchEvent(new PopStateEvent('popstate'))});await ready();
  await page.goBack();await page.getByRole('link',{name:'鸟瞰地图',exact:true}).waitFor({state:'visible'});
  assert(new URL(page.url()).searchParams.get('view')==='street','Cross-view back');
  await page.goForward();await ready();assert(new URL(page.url()).searchParams.get('view')==='atlas','Cross-view forward');
  checks.push({same_document_view_history:true});
  await goto('?view=atlas&area=south&category=dining&q=N31');
  await page.locator('[data-record="N31"]').click();await ready();
  await page.getByRole('button',{name:'清空搜索',exact:true}).click();await ready();
  assert(await page.locator('.atlas-detail').count()===0 && !new URL(page.url()).searchParams.has('building'),'Clear cross-region selection');
  await cat('校门');await page.getByRole('navigation',{name:'校园区域'}).getByRole('button',{name:'全校总览',exact:true}).click();await ready();
  assert(await page.locator('.atlas-overview-intro').count()===0 && await page.locator('.atlas-filter-banner').count()===1,'Filter/overview overlap');
  await page.route('**/campus-atlas.json*',async route=>{await new Promise(resolve=>setTimeout(resolve,1800));await route.continue()});
  await page.goto('http://127.0.0.1:5173/?view=atlas&area=south');
  await input.fill('S1');await ready();await page.unroute('**/campus-atlas.json*');
  assert(await input.inputValue()==='S1' && (await ids())[0]==='S01','Loading discarded typed query');
  const validMeta=await(await page.request.get('http://127.0.0.1:5173/campus-atlas.json')).json();
  await page.route('**/campus-atlas.json*',async route=>{await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({...validMeta,map_places:{...validMeta.map_places,image_sha256:'0'.repeat(64)}})})});
  await page.goto('http://127.0.0.1:5173/?view=atlas&area=south');
  await page.getByRole('button',{name:'重新加载',exact:true}).waitFor({state:'visible'});
  assert(await page.locator('.atlas-map').evaluate(map=>map.inert),'Invalid projection must block map');
  await page.unroute('**/campus-atlas.json*');
  await page.getByRole('button',{name:'重新加载',exact:true}).click();await ready();
  checks.push({clear_cross_region_selection:true,filter_overview_no_overlap:true,loading_preserves_query:true,mismatched_projection_retry:true});
  await goto('?view=atlas&area=south');
  assert(!errors.length,'Runtime/console errors '+JSON.stringify(errors));
  return {status:'passed',scope:'Local source-backed atlas interaction slice; reference website parity not achieved',checks,captures,errors,limitations:['No true device/soft keyboard/Safari','No verified route network or official facility identity crosswalk','External panorama availability not verified','Satellite tile quality and all source-site functions not audited']};
}
